MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M t USING (SELECT 'EndCustomerByDivision40' AS SQL_ID, 'DM' AS MDU_DIVS_CD, '[C] AS-IS @Code=''EndCustomerByDivision40'' 수작업 통합 변환 — 빈 파라미터 0행 함정 ' AS SQL_NM, 'SELECT DISTINCT A.PROJECT_CODE AS CODE, NVL(D.SEGMENT3, A.PROJECT_CODE) AS NAME FROM SCM_MGR.SCM_MST_SITE_ITEM A JOIN SCM_MGR.SCM_MST_SSO_USER_INFO B ON B.USER_ID = TRIM(CASE WHEN INSTR(A.OWNER, '','') > 0 THEN SUBSTR(A.OWNER, 1, INSTR(A.OWNER, '','') - 1) ELSE A.OWNER END) JOIN SCM_MGR.SCM_MST_SSO_DEPT_INFO C ON C.DEPT_ID = B.DEPT_ID LEFT JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL D ON A.DIVISION_ID = D.SEGMENT1 AND A.PROJECT_CODE = D.SEGMENT2 AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y'' WHERE A.DIVISION_ID = ''40'' AND A.VALID_YN = ''Y'' UNION SELECT SEGMENT2, SEGMENT3 FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = ''END_CUSTOMER'' AND SEGMENT1 = ''40'' AND SEGMENT2 <> ''-'' AND VALID_YN = ''Y'' ORDER BY 1' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'minyonglee1' AS CREATED_BY, TO_DATE('2026-07-02 23:24:25','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'minyonglee1' AS LAST_UPDATED_BY, TO_DATE('2026-07-02 23:24:25','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) s
